package com.alsafa.native4;
import android.app.*;import android.os.Bundle;import android.database.Cursor;import android.content.ContentValues;import android.widget.*;import android.view.*;import com.alsafa.native4.core.*;import org.json.JSONObject;import com.google.firebase.firestore.DocumentSnapshot;import com.google.firebase.firestore.QuerySnapshot;
public final class SyncCenterActivity extends Activity{
 private CoreDb db;private LinearLayout list;private TextView status;private LinearLayout tabs;private TextView counts;private int selectedTab=0;private int visibleLimit=40;private volatile String peerSummary="لم يتم فحص استلام الأجهزة الأخرى";private volatile java.util.Map<String,Long> peerRevisions=java.util.Collections.emptyMap();
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new CoreDb(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,24,20,12);status=new TextView(this);status.setTextSize(19);root.addView(status);counts=new TextView(this);root.addView(counts);TextView peers=new TextView(this);root.addView(peers);Button verify=new Button(this);verify.setText("التحقق من استلام الأجهزة");root.addView(verify);verify.setOnClickListener(v->{peerSummary="جاري فحص تأكيدات الأجهزة";peers.setText(peerSummary);new Thread(()->{String report;try{QuerySnapshot result=Native4DeviceReceipt.readReceipts();String self=Native4DeviceReceipt.deviceId(this);StringBuilder summary=new StringBuilder();java.util.Map<String,Long> revisions=new java.util.HashMap<>();for(DocumentSnapshot d:result.getDocuments()){String id=d.getString("deviceId");Long revision=d.getLong("appliedRevision");if(id!=null&&!id.equals(self)&&revision!=null){revisions.put(id,revision);if(summary.length()>0)summary.append("\n");summary.append("الجهاز ").append(id).append(": طبّق العمليات حتى المراجعة ").append(revision);}}peerRevisions=java.util.Collections.unmodifiableMap(revisions);report=summary.length()==0?"لا يوجد تأكيد استلام من جهاز آخر":summary.toString();}catch(Exception e){peerRevisions=java.util.Collections.emptyMap();report="تعذر التحقق من الخادم: "+e.getClass().getSimpleName();}peerSummary=report;runOnUiThread(()->{peers.setText(peerSummary);refresh();});},"native4-peer-receipts").start();});peers.setText(peerSummary);Button sync=new Button(this);sync.setText("مزامنة الآن");root.addView(sync);tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);root.addView(tabs);sync.setOnClickListener(v->{Native4AutoSync.requestImmediate(this,db,this::refresh);refresh();});ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);refresh();}
 @Override protected void onResume(){super.onResume();refresh();}
 private void refresh(){status.setText(Native4AutoSync.status());updateCounts();tabs.removeAllViews();String[] titles={"المعلقة","المرسلة","المستقبلة"};for(int i=0;i<titles.length;i++){final int tab=i;Button b=new Button(this);b.setText(titles[i]);b.setAllCaps(false);b.setEnabled(i!=selectedTab);tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{selectedTab=tab;visibleLimit=40;refresh();});}list.removeAllViews();if(selectedTab==2)showReceived();else showOutgoing();}
 private void updateCounts(){try(Cursor q=db.db().rawQuery("SELECT state,COUNT(*) FROM outbox GROUP BY state",null)){int pending=0,sent=0,failed=0;while(q.moveToNext()){String state=q.getString(0);int n=q.getInt(1);if("CONFIRMED".equals(state))sent+=n;else{pending+=n;if("FAILED".equals(state))failed+=n;}}counts.setText("معلقة: "+pending+" | رُفعت: "+sent+" | للمراجعة: "+failed);}catch(Exception e){counts.setText("الإحصاءات غير متاحة");}}
 private void showOutgoing(){String where=selectedTab==0?"WHERE state != 'CONFIRMED'":"WHERE state = 'CONFIRMED'";int count=0;try(Cursor c=db.db().rawQuery("SELECT operation_id,operation_kind,record_id,payload,state,attempts,last_error,confirmed_revision FROM outbox "+where+" ORDER BY created_at DESC LIMIT "+(visibleLimit+1),null)){while(c.moveToNext()){count++;if(count>visibleLimit)break;String id=c.getString(0),kind=c.getString(1),record=c.getString(2),payload=c.getString(3),state=c.getString(4),error=c.getString(6);int attempts=c.getInt(5);long revision=c.isNull(7)?0:c.getLong(7);String name=label(kind,record,payload);Button item=new Button(this);item.setAllCaps(false);item.setText(name+"\n"+stateName(state)+peerReceiptLabel(state,revision));list.addView(item);item.setOnClickListener(v->details(id,name,attempts,error));}}catch(Exception e){message("تعذر قراءة عمليات الإرسال: "+e.getMessage());}if(count>visibleLimit)more();if(count==0)message("لا توجد عمليات في هذا القسم");}
 private String peerReceiptLabel(String state,long revision){if(!"CONFIRMED".equals(state)||revision<=0)return "";java.util.Map<String,Long> peers=peerRevisions;if(peers.isEmpty())return "\nاستلام الجهاز الآخر: غير متحقق منه";StringBuilder s=new StringBuilder();for(java.util.Map.Entry<String,Long> peer:peers.entrySet()){s.append("\nالجهاز ").append(peer.getKey()).append(": ").append(peer.getValue()>=revision?"أكد تطبيق العملية":"لم يؤكد تطبيق العملية");}return s.toString();}
 private void showReceived(){int count=0;try(Cursor c=db.db().rawQuery("SELECT operation_id,operation_kind,record_id,payload,source_device_id,revision FROM received_sync_log ORDER BY received_at DESC LIMIT "+(visibleLimit+1),null)){while(c.moveToNext()){count++;if(count>visibleLimit)break;String id=c.getString(0),kind=c.getString(1),record=c.getString(2),payload=c.getString(3),device=c.getString(4);long revision=c.getLong(5);String name=label(kind,record,payload);Button item=new Button(this);item.setAllCaps(false);item.setText(name+"\nتم الاستقبال والتطبيق");list.addView(item);item.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(name).setMessage("تم التطبيق على هذا الجهاز\nالمصدر: "+device+"\nمعرّف العملية: "+id+"\nالمراجعة: "+revision).setPositiveButton("إغلاق",null).show());}}catch(Exception e){message("سجل الاستقبال غير متاح: "+e.getMessage());}if(count>visibleLimit)more();if(count==0)message("لا توجد عمليات مستقبلة مسجلة");}
 private void more(){Button b=new Button(this);b.setText("عرض المزيد");list.addView(b);b.setOnClickListener(v->{visibleLimit+=40;refresh();});}
 private void message(String s){TextView t=new TextView(this);t.setText(s);list.addView(t);}
 private void details(String id,String name,int attempts,String error){String state;try(Cursor c=db.db().rawQuery("SELECT state FROM outbox WHERE operation_id=?",new String[]{id})){if(!c.moveToFirst())return;state=c.getString(0);}String msg="الحالة: "+stateName(state)+"\nالمعرّف: "+id+"\nالمحاولات: "+attempts+"\nالخطأ: "+(error==null?"لا يوجد":error);AlertDialog.Builder d=new AlertDialog.Builder(this).setTitle(name).setMessage(msg).setNegativeButton("إغلاق",null);if("PENDING".equals(state)||"RETRY".equals(state))d.setPositiveButton("إعادة محاولة الرفع",(dialog,which)->retry(id));else if("FAILED".equals(state))d.setPositiveButton("إعادة الفحص",(dialog,which)->new AlertDialog.Builder(this).setTitle("إعادة فحص العملية الفاشلة").setMessage("ستُعاد محاولة إرسال العملية نفسها بالمعرّف والمحتوى الأصليين، دون إنشاء فاتورة أو حركة مالية جديدة. إذا كان الخطأ تعارضًا في بيانات Firebase فقد يستمر التوقف، ولن يتم تجاوز التعارض تلقائيًا. هل تريد المتابعة؟").setNegativeButton("إلغاء",null).setPositiveButton("إعادة الفحص الآن",(confirm,whichConfirm)->retryFailed(id)).show());d.show();}
 private void retry(String id){ContentValues v=new ContentValues();v.put("state","RETRY");int n=db.db().update("outbox",v,"operation_id=? AND state IN ('PENDING','RETRY')",new String[]{id});if(n==1){Native4AutoSync.requestImmediate(this,db,this::refresh);}else{message("تعذرت إعادة المحاولة؛ قد تتطلب العملية فحصًا أو تكون حالتها قد تغيرت");}refresh();}
 private void retryFailed(String id){ContentValues v=new ContentValues();v.put("state","RETRY");int n=db.db().update("outbox",v,"operation_id=? AND state='FAILED'",new String[]{id});if(n==1){Native4AutoSync.requestImmediate(this,db,this::refresh);}else{message("تغيرت حالة العملية؛ أعد فتح تفاصيلها للتحقق");}refresh();}
 private static String label(String kind,String id,String payload){String type=kind==null?"عملية":kind;switch(type){case "SALE":case "SALE_CREATE":case "SALE_UPDATE":type="مبيع";break;case "REPAIR":case "REPAIR_UPDATE":type="صيانة";break;case "PRODUCT_CREATE":case "PRODUCT_UPDATE":case "PRODUCT_DELETE":type="منتج";break;case "PURCHASE":type="شراء";break;}String name="";try{JSONObject j=new JSONObject(payload);name=type.equals("منتج")?j.optString("name",j.optString("productName","")):type.equals("مبيع")||type.equals("صيانة")?j.optString("invoiceNo",""):type.equals("شراء")?j.optString("invoiceRef",""):"";}catch(Exception ignored){}return type+" — "+(name.isEmpty()?id:name);}
 private static String stateName(String s){if("CONFIRMED".equals(s))return "تم الرفع";if("SENDING".equals(s))return "قيد الرفع";if("FAILED".equals(s))return "فشل";if("RETRY".equals(s))return "بانتظار إعادة المحاولة";return "بانتظار الرفع";}
}